{
  "action": "set_channel",
  "input": {
    "channel": 5
  }
}

// Set volume to 15
{
  "action": "adjust_volume",
  "input": {
    "volume": 15
  }
}

// Turn the TV off
{
  "action": "turn_off"
}
```

> **Note**: `channel` and `volume` are integers. Ensure the values are within the supported range of your TV.

