{
  "action": "turnOn"
}

// Set channel to 5
{
  "action": "setChannel",
  "input": { "channel": 5 }
}

// Set volume to 20
{
  "action": "setVolume",
  "input": { "level": 20 }
}

// Turn the TV off
{
  "action": "turnOff"
}
```

